def check(world, calls):
    verify_calls = [c for c in calls if c.name == "verify_billing_admin" and c.ok]
    if not verify_calls:
        return "not done: verify_billing_admin was not called successfully"
    admin_calls = [c for c in verify_calls if c.result.get("is_admin") is True]
    if not admin_calls:
        return "not done: caller was not verified as a billing admin"
    return None

def check(world, calls):
    cancel_calls = [c for c in calls if c.name == "cancel_scheduled_change" and c.ok]
    if not cancel_calls:
        return "not done: cancel_scheduled_change was not called successfully"
    canceled_records = [r for r in world.state().get("scheduled_changes", []) if r.get("status") == "canceled"]
    if not canceled_records:
        return "not done: no scheduled change was marked canceled in world state"
    for c in cancel_calls:
        cid = c.arguments.get("change_id")
        tid = c.arguments.get("tenant_id")
        match = [r for r in canceled_records if r.get("change_id") == cid and r.get("tenant_id") == tid]
        if not match:
            return f"done wrong: change {cid!r} for tenant {tid!r} is not marked canceled in world state"
    return None

def check(world, calls):
    sched_calls = [c for c in calls if c.name == "schedule_plan_change" and c.ok]
    if not sched_calls:
        return "not done: schedule_plan_change was not called"

    pending = [r for r in world.state().get("scheduled_changes", []) if r.get("status") == "pending"]
    if not pending:
        return "not done: no pending scheduled change found in world state"

    for c in sched_calls:
        tid = c.arguments.get("tenant_id")
        t_pending = [r for r in pending if r.get("tenant_id") == tid]
        if len(t_pending) > 1:
            return f"done wrong: duplicate pending changes created for tenant {tid!r}"
        if len(t_pending) == 1:
            sc = t_pending[0]
            if c.arguments.get("target_plan_id") and sc.get("target_plan_id") != c.arguments.get("target_plan_id"):
